const result = await generateText({
  model: yourModel,
  prompt: 'Hello',
  include: {
    requestBody: true,
    responseBody: true,
  },
});
```


For `streamText`, only `requestBody` is available:

```tsx title="AI SDK 7"
const result = streamText({
  model: yourModel,
  prompt: 'Hello',
  include: {
